def compute(vars):
    net_of_tax_charge = vars["v1"]
    taxes = vars["v2"]
    before_tax_charge = net_of_tax_charge + taxes

    return {
        "value": before_tax_charge,
        "trace": {
            "net_of_tax_charge": net_of_tax_charge,
            "taxes": taxes,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": None
            }
        }
    }
